DROP TABLE IF EXISTS `docket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `docket` (
  `docket_id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `tab` enum('prompt','media') DEFAULT 'prompt',
  `business_id` bigint NOT NULL,
  `product_id` bigint DEFAULT NULL,
  `persona_id` bigint DEFAULT NULL,
  `media_id` bigint NOT NULL,
  `media_type_id` bigint NOT NULL,
  `media_subtype_id` bigint NOT NULL,
  `planner_date_time` datetime NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`docket_id`),
  KEY `fk_docket_business` (`business_id`),
  KEY `fk_docket_product` (`product_id`),
  KEY `fk_docket_persona` (`persona_id`),
  KEY `fk_docket_media` (`media_id`),
  KEY `fk_docket_media_type` (`media_type_id`),
  KEY `fk_docket_media_subtype` (`media_subtype_id`),
  CONSTRAINT `fk_docket_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`business_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_docket_media` FOREIGN KEY (`media_id`) REFERENCES `media` (`media_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_docket_media_subtype` FOREIGN KEY (`media_subtype_id`) REFERENCES `media_subtype` (`media_subtype_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_docket_media_type` FOREIGN KEY (`media_type_id`) REFERENCES `media_type` (`media_type_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_docket_persona` FOREIGN KEY (`persona_id`) REFERENCES `personas` (`persona_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_docket_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

