INSERT INTO `docket_media_results` VALUES (1,55,NULL,'==============================\n      VISUAL INFORMATION\n      ==============================\n\n      Mode: visuals\n      Media Type: comparative\n      Media Sub Type: Product A vs Product B\n\n\n      ------------------------------\n      BUSINESS INFORMATION\n      ------------------------------\n      • Business Id: 1\n• Profile Id: 1\n• Business Name: visualgrab\n• Created At: 2026-02-09T20:11:56\n• Updated At: 2026-03-06T16:14:06\n• Is Completed: 1\n• Business Type: Advertising & Marketing\n• Industry: Advertising Agency\n• Year Established: 2010\n• Terms Accepted: 1\n• Privacy Accepted: 1\n\n      ------------------------------\n      PERSONA INFORMATION\n      ------------------------------\n      \n          Persona Name: person 12\n\n          • demographic - Age: 18\n• demographic - other: sfsdf\n          \n\n      ------------------------------\n      PRODUCT INFORMATION\n      ------------------------------\n      \n        • Product Name: ghvhhb\n\n        Features:\n        \n\n        USPs:\n        \n\n        Values:\n        \n\n        Product Images:\n        \n        \n\n      ------------------------------\n      DYNAMIC FIELD VALUES\n      ------------------------------\n      • beforePersona: djshfkljasdfkjdaskfjsdakfjklasd\n• beforeProblem: Struggling with a generic, cumbersome tool (Product B) that makes common tasks time-consuming and frustrating, leading to missed opportunities or subpar results.\n• beforeEmotion: Frustrated, stressed, impatient, feeling limited by current solutions.\n• beforeEnvironment: Sitting in front of a laptop screen, surrounded by multiple open tabs and disorganized files, in a typical student or home office setting.\n• beforeText: Why is this so slow? There has to be a better way to get things done.\n• afterSupport: Product A (ghvhhb) provides intuitive features and a streamlined interface that simplify complex tasks, offering a noticeable advantage in efficiency and user experience compared to Product B.\n• afterOutcome: The persona effortlessly completes tasks, achieves desired results faster, and experiences a significant boost in productivity and creative flow, surpassing the limitations of Product B.\n• afterEmotion: Confident, relieved, satisfied, empowered, and excited by the new possibilities.\n• afterText: This is a game-changer! Everything just works seamlessly now.\n• mood: Transformative, empowering, innovative, efficient.\n• theme: Efficiency vs. Complexity, Innovation vs. Stagnation, Seamless Workflow, Modern Productivity.\n• tone: Enthusiastic, persuasive, solution-oriented, modern.\n• colorPreference: Vibrant and dynamic colors for Product A\'s side (e.g., bright blues, greens, purples) contrasting with duller, more muted tones for Product B\'s side (e.g., grays, desaturated yellows, browns).\n• finishType: Clean, modern, digitally rendered, possibly with UI/UX elements highlighted, showing a clear visual comparison of two interfaces or user experiences.',1,'2026-03-06 13:05:01',0,NULL),(2,55,NULL,'==============================\n      VISUAL INFORMATION\n      ==============================\n\n      Mode: visuals\n      Media Type: comparative\n      Media Sub Type: Product A vs Product B\n\n\n      ------------------------------\n      BUSINESS INFORMATION\n      ------------------------------\n      • Business Id: 1\n• Profile Id: 1\n• Business Name: visualgrab\n• Created At: 2026-02-09T20:11:56\n• Updated At: 2026-03-06T16:14:06\n• Is Completed: 1\n• Business Type: Advertising & Marketing\n• Industry: Advertising Agency\n• Year Established: 2010\n• Terms Accepted: 1\n• Privacy Accepted: 1\n\n      ------------------------------\n      PERSONA INFORMATION\n      ------------------------------\n      \n          Persona Name: person 12\n\n          • demographic - Age: 18\n• demographic - other: sfsdf\n          \n\n      ------------------------------\n      PRODUCT INFORMATION\n      -----------