DROP TABLE IF EXISTS `media_subtype_field_value`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `media_subtype_field_value` (
  `media_subtype_field_value_id` bigint NOT NULL AUTO_INCREMENT,
  `docket_id` bigint NOT NULL,
  `label` varchar(255) NOT NULL,
  `value` text,
  `checkbox_clicked` tinyint(1) NOT NULL DEFAULT '1',
  `box` enum('mandatory','optional') NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `field_source` enum('default','custom') NOT NULL DEFAULT 'default',
  PRIMARY KEY (`media_subtype_field_value_id`),
  UNIQUE KEY `unique_docket_label` (`docket_id`,`label`),
  KEY `idx_docket_id` (`docket_id`),
  CONSTRAINT `fk_media_field_docket` FOREIGN KEY (`docket_id`) REFERENCES `docket` (`docket_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2854 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
